sys_script_client.script:
function onSubmit() {
    // Clear previous error messages
    g_form.clearMessages();

    // Helper function to extract digits and check if exactly 10 user digits were entered
    function validate10Digits(fieldName, fieldLabel) {
        var rawVal = g_form.getValue(fieldName);
        if (!rawVal) return true; // Allow empty/optional fields to pass

        // Extract numbers only
        var digitsOnly = rawVal.toString().replace(/\D/g, '');

        // If E164 automatically included India country code 91 at the start, strip it out to check the subscriber number
        if (digitsOnly.length > 10 && digitsOnly.startsWith('91')) {
            digitsOnly = digitsOnly.substring(2);
        }

        // Check if the remaining number is exactly 10 digits long
        if (digitsOnly.length !== 10) {
            g_form.addErrorMessage(fieldLabel + ' must contain exactly 10 digits (currently ' + digitsOnly.length + ' digits).');
            return false;
        }
        return true;
    }

    // Run validations
    var fatherValid = validate10Digits('father_mobile_number', 'Father Mobile Number');
    var motherValid = validate10Digits('mother_mobile_number', 'Mother Mobile Number');

    // Block submit if either field is invalid
    if (!fatherValid || !motherValid) {
        return false;
    }

    return true;
}
